/// Create the parent directories and write the header line.
pub fn start_journal(path: &std::path::Path, header: &str) -> std::io::Result<()>
/// Append one line and a newline, then flush.
pub fn append_journal(path: &std::path::Path, line: &str) -> std::io::Result<()>
/// The header and the lines that parse. A damaged last line is dropped. A missing header is InvalidData.
pub fn read_journal(path: &std::path::Path) -> std::io::Result<(JournalHeader, Vec<JournalLine>)>
/// Remove the file. NotFound is Ok.
pub fn clear_journal(path: &std::path::Path) -> std::io::Result<()>
